  letter-spacing: var(--tracking-wide);
  color: var(--color-text-primary);
  background: var(--color-purple);
  border-radius: var(--radius-sm);
  opacity: 1;
}
.ts-item.ts-cta-primary:hover,
.ts-item.ts-cta-primary.is-selected {
  color: var(--color-text-primary);
  background: var(--color-purple-bright);
}

input.new_string:
  letter-spacing: var(--tracking-wide);
  color: #fff;
  background: var(--color-purple);
  border-radius: var(--radius-sm);
  opacity: 1;
}
/* Selection brightens the *frame*, not the fill — a lighter purple fill drops
   the label below readable contrast (the button boots selected). */
.ts-item.ts-cta-primary:hover,
.ts-item.ts-cta-primary.is-selected {
  color: #fff;
  background: var(--color-purple);
  outline: 1px solid var(--color-accent);
  outline-offset: 2px;
  box-shadow: 0 0 16px rgba(0, 229, 196, 0.35);
}

